fn has_explicit_scope_raw(args: &[String]) -> bool {
    // Find positional args before "--"
    // Skip binary name
    let mut found_scope = false;
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" {
            break;
        }
        if arg.starts_with("--") {
            // Long option: check if it takes value
            // For simplicity, if it contains "=", it's one arg, else if next arg exists and is not starting with "-", it could be value.
            // We will skip value if option is known to take value
            let takes_value = is_option_takes_value_long(arg);
            if takes_value {
                if !arg.contains('=') {
                    i += 1; // skip next as value
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // Short options: could be combined
            // For simplicity, if arg is "-G" or similar that takes value, skip next
            // Check if any short option in combined takes value
            let mut chars = arg.chars().skip(1);
            let mut takes_val = false;
            for c in chars {
                if is_option_takes_value_short(c) {
                    takes_val = true;
                    break;
                }
            }
            if takes_val {
                // If arg like "-Gvalue" or "-G=val", we already have value in same arg, else skip next
                if arg.len() == 2 {
                    i += 1;
                }
            }
        } else {
            // Positional arg
            if !found_scope {
                found_scope = true;
            } else {
                // Second positional would be error, but we have found at least one
            }
        }
        i += 1;
    }
    found_scope
}

fn is_option_takes_value_long(arg: &str) -> bool {
    let name = arg.split('=').next().unwrap();
    matches!(name, "--completions" | "-G" | "--glob" | "--stdin-detection" | "--stdout-detection" | "--threads" | "--c" | "--c-query" | "--c-query-file" | "--csharp" | "--cs" | "--csharp-query" | "--csharp-query-file" | "--go" | "--go-query" | "--go-query-file" | "--hcl" | "--hcl-query" | "--hcl-query-file" | "--python" | "--py" | "--python-query" | "--python-query-file" | "--rust" | "--rs" | "--rust-query" | "--rust-query-file" | "--typescript" | "--ts" | "--typescript-query" | "--typescript-query-file")
}

fn is_option_takes_value_short(c: char) -> bool {
    matches!(c, 'G')
}

