fn expand_replacement(rep: &str, caps: HashMap<String,String>) -> String {
    // Expand $1, $2, $NAME, ${NAME}, $$?
    // Very simplified: replace $1, $2 etc and $NAME
    // We have caps containing numbered keys "0", "1", etc and named keys
    let mut result = String::new();
    let mut chars = rep.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '$' {
            if let Some(&next) = chars.peek() {
                if next == '$' {
                    // $$ -> $
                    result.push('$');
                    chars.next();
                } else if next.is_ascii_digit() {
                    // Parse number
                    let mut num_str = String::new();
                    while let Some(&d) = chars.peek() {
                        if d.is_ascii_digit() {
                            num_str.push(d);
                            chars.next();
                        } else {
                            break;
                        }
                    }
                    if let Some(val) = caps.get(&num_str) {
                        result.push_str(val);
                    }
                } else if next == '{' {
                    // ${NAME}
                    chars.next(); // consume {
                    let mut name = String::new();
                    while let Some(ch) = chars.next() {
                        if ch == '}' {
                            break;
                        }
                        name.push(ch);
                    }
                    if let Some(val) = caps.get(&name) {
                        result.push_str(val);
                    }
                } else if next.is_alphabetic() || next == '_' {
                    // $NAME
                    let mut name = String::new();
                    while let Some(&ch) = chars.peek() {
                        if ch.is_alphanumeric() || ch == '_' {
                            name.push(ch);
                            chars.next();
                        } else {
                            break;
                        }
                    }
                    if let Some(val) = caps.get(&name) {
                        result.push_str(val);
                    }
                } else {
                    result.push('$');
                }
            } else {
                result.push('$');
            }
        } else {
            result.push(c);
        }
    }
    result
}

