            'À'|'Á'|'Â'|'Ã'|'Ä'|'Å' => 'A',
            'à'|'á'|'â'|'ã'|'ä'|'å' => 'a',
            'Ç'|'ç' => if c.is_uppercase() {'C'} else {'c'},
            'È'|'É'|'Ê'|'Ë' => 'E',
            'è'|'é'|'ê'|'ë' => 'e',
