            'ò'|'ó'|'ô'|'õ'|'ö' => 'o',
            'Ù'|'Ú'|'Û'|'Ü' => 'U',
            'ù'|'ú'|'û'|'ü' => 'u',
            'Ý' => 'Y',
            'ý'|'ÿ' => 'y',
            _ => c,
        };
        result.push(mapped);
