    let mut i = 0;
    while i < chars.len() {
        let mut matched = false;
        // Check each mapping
        for (ascii, unicode) in &mappings {
            let ascii_chars: Vec<char> = ascii.chars().collect();
            if i + ascii_chars.len() <= chars.len() {
                let slice: String = chars[i..i+ascii_chars.len()].iter().collect();
                if slice == *ascii {
                    // For non-naive, apply heuristic
                    if !naive {
                        // Heuristic: if ascii is "ue" or "Ue" etc and preceded by 'a' or 'e' (case-insensitive)
                        let lower_ascii = ascii.to_lowercase();
                        if lower_ascii == "ue" {
                            // Check preceding char
                            if i > 0 {
                                let prev = chars[i-1].to_lowercase().to_string();
                                if prev == "a" || prev == "e" {
                                    // Check if it's part of "auer" or "euer" etc: if next char after "ue" is 'r' or 'n' or 'm'?
                                    // For "Bauer", after "ue" is 'r', so skip
                                    // For "Frauen", after "ue" is 'n', skip?
                                    // For "Abenteuer", after "ue" is 'r', skip
                                    // For "feuer", after "ue" is 'r', skip
                                    // So if next char after ue is r, n, maybe skip
                                    if i + ascii_chars.len() < chars.len() {
                                        let next = chars[i+ascii_chars.len()].to_lowercase().to_string();
                                        if next == "r" || next == "n" {
                                            // Skip replacement
                                            continue;
                                        }
                                    }
                                }
                            }
                        }
                        // For "oe" in "Koeffizienten", we need to skip when preceded by 'o' ?
                        // Koeffizienten has "oe" preceded by 'o'
                        if lower_ascii == "oe" {
                            if i > 0 {
                                let prev = chars[i-1].to_lowercase().to_string();
                                if prev == "o" {
                                    continue;
                                }
                            }
                        }
                    }

                    // For prefer_original, if ambiguous, skip (handled earlier for whole word, but we need per word)
                    if prefer_original {
                        // If original word is ambiguous, skip
                        // For simplicity, we already handled whole string ambiguous, but for compound we need more
                    }

                    output.push_str(unicode);
                    i += ascii_chars.len();
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            output.push(chars[i]);
            i += 1;
        }
    }

    output
}

fn get_lang_intervals(input: &str, lang_scopes: &[(String,String)], join: bool) -> Vec<(usize,usize)> {
    // Simplified heuristic for Python at least
    // For each lang scope, we compute intervals
    // For now, we only implement Python class, def, comments, strings, etc via regex

    let mut intervals: Vec<(usize,usize)> = Vec::new();

    for (lang, query) in lang_scopes {
        let lang_intervals = match lang.as_str() {
            "python" | "py" => get_python_intervals(input, query),
            "rust" | "rs" => get_rust_intervals(input, query),
            "go" => get_go_intervals(input, query),
            "typescript" | "ts" => get_typescript_intervals(input, query),
            "c" => get_c_intervals(input, query),
            "csharp" | "cs" => get_csharp_intervals(input, query),
            "hcl" => get_hcl_intervals(input, query),
            _ => vec![(0, input.len())], // For query variants, treat as whole file for now
        };
        if intervals.is_empty() {
            intervals = lang_intervals;
        } else {
            if join {
                // OR: union
                intervals.extend(lang_intervals);
                // Merge overlapping
                intervals = merge_intervals(intervals);
            } else {
                // AND: intersect
                intervals = intersect_intervals(&intervals, &lang_intervals);
            }
        }
    }

    if intervals.is_empty() {
        vec![(0, input.len())]
    } else {
        intervals
    }
}

fn merge_intervals(mut intervals: Vec<(usize,usize)>) -> Vec<(usize,usize)> {
    if intervals.is_empty() {
        return intervals;
    }
    intervals.sort_by_key(|(s,_)| *s);
    let mut merged = vec![intervals[0]];
    for (s,e) in intervals.into_iter().skip(1) {
        let last = merged.last_mut().unwrap();
        if s <= last.1 {
            last.1 = last.1.max(e);
        } else {
            merged.push((s,e));
        }
    }
    merged
}

fn intersect_intervals(a: &[(usize,usize)], b: &[(usize,usize)]) -> Vec<(usize,usize)> {
    let mut result = Vec::new();
    for (s1,e1) in a {
        for (s2,e2) in b {
            let s = (*s1).max(*s2);
            let e = (*e1).min(*e2);
            if s < e {
                result.push((s,e));
            }
        }
    }
    merge_intervals(result)
}

fn get_python_intervals(input: &str, query: &str) -> Vec<(usize,usize)> {
    // Very simplified: handle common queries
    match query {
        "comments" => {
            // Find # comments
            let re = Regex::new(r"#.*").unwrap();
            let mut v = Vec::new();
            for m in re.find_iter(input) {
                v.push((m.start(), m.end()));
            }
            v
        },
        "strings" => {
            // Find strings: ".*?" and '.*?' and triple quotes
            // Simplified: match ".*?" and '.*?' (non-greedy)
            let re = Regex::new(r#""[^"]*"|'[^']*'"#).unwrap();
            let mut v = Vec::new();
            for m in re.find_iter(input) {
                v.push((m.start(), m.end()));
            }
            v
        },
        "class" => {
            // Class definition including indented body? Simplified: from "class" to next dedent or next class/def at same indent?
            // For simplicity, match "class.*:\n( {4}.*\n)*"
            let re = Regex::new(r"(?m)^class\s+\w+.*:\n(?:[ \t]+.*\n?)*").unwrap();
            let mut v = Vec::new();
            for m in re.find_iter(input) {
                v.push((m.start(), m.end()));
            }
            if v.is_empty() {
                // Fallback: just the line with class
                let re2 = Regex::new(r"(?m)^.*class.*$").unwrap();
                for m in re2.find_iter(input) {
                    v.push((m.start(), m.end()));
                }
            }
            v
        },
        "def" => {
            let re = Regex::new(r"(?m)^ *def\s+\w+.*:\n(?:[ \t]+.*\n?)*").unwrap();
            let mut v = Vec::new();
            for m in re.find_iter(input) {
                v.push((m.start(), m.end()));
            }
            if v.is_empty() {
                let re2 = Regex::new(r"(?m)^.*def.*$").unwrap();
                for m in re2.find_iter(input) {
                    v.push((m.start(), m.end()));
                }
            }
            v
        },
        _ => {
            // For other queries, return whole file for now
            vec![(0, input.len())]
        }
    }
}

fn get_rust_intervals(input: &str, query: &str) -> Vec<(usize,usize)> {
    match query {
        "comments" => {
            let re = Regex::new(r"//.*|/\*.*?\*/").unwrap();
            let mut v = Vec::new();
            for m in re.find_iter(input) {
                v.push((m.start(), m.end()));
            }
            v
        },
        "strings" => {
            let re = Regex::new(r#""[^"]*""#).unwrap();
            let mut v = Vec::new();
            for m in re.find_iter(input) {
                v.push((m.start(), m.end()));
            }
            v
        },
        _ => vec![(0, input.len())],
    }
}

