fn has_explicit_scope_raw(args: &[String]) -> bool {
    // Find positional args before "--"
    // Skip binary name
    let mut found_scope = false;
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" {
            break;
        }
        if arg.starts_with("--") {
            // Long option: check if it takes value
            // For simplicity, if it contains "=", it's one arg, else if next arg exists and is not starting with "-", it could be value.
            // We will skip value if option is known to take value
            let takes_value = is_option_takes_value_long(arg);
            if takes_value {
                if !arg.contains('=') {
                    i += 1; // skip next as value
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // Short options: could be combined
            // For simplicity, if arg is "-G" or similar that takes value, skip next
            // Check if any short option in combined takes value
            let mut chars = arg.chars().skip(1);
            let mut takes_val = false;
            for c in chars {
                if is_option_takes_value_short(c) {
                    takes_val = true;
                    break;
                }
            }
            if takes_val {
                // If arg like "-Gvalue" or "-G=val", we already have value in same arg, else skip next
                if arg.len() == 2 {
                    i += 1;
                }
            }
        } else {
            // Positional arg
            if !found_scope {
                found_scope = true;
            } else {
                // Second positional would be error, but we have found at least one
            }
        }
        i += 1;
    }
    found_scope
}

fn is_option_takes_value_long(arg: &str) -> bool {
    let name = arg.split('=').next().unwrap();
    matches!(name, "--completions" | "-G" | "--glob" | "--stdin-detection" | "--stdout-detection" | "--threads" | "--c" | "--c-query" | "--c-query-file" | "--csharp" | "--cs" | "--csharp-query" | "--csharp-query-file" | "--go" | "--go-query" | "--go-query-file" | "--hcl" | "--hcl-query" | "--hcl-query-file" | "--python" | "--py" | "--python-query" | "--python-query-file" | "--rust" | "--rs" | "--rust-query" | "--rust-query-file" | "--typescript" | "--ts" | "--typescript-query" | "--typescript-query-file")
}

fn is_option_takes_value_short(c: char) -> bool {
    matches!(c, 'G')
}

fn process_content(
    input: &str,
    filename: &str,
    scope_pattern: &str,
    literal: bool,
    replacement: Option<String>,
    upper: bool,
    lower: bool,
    titlecase: bool,
    normalize: bool,
    german: bool,
    german_naive: bool,
    german_prefer_original: bool,
    symbols: bool,
    invert: bool,
    delete: bool,
    squeeze: bool,
    lang_scopes: &[(String, String)],
    join_lang: bool,
    line_numbers: bool,
    only_matching: bool,
    has_actions: bool,
    search_mode: bool,
) -> (String, bool) {
    // Returns (output, in_scope_found)
    // For search_mode without actions, output is search results
    // For actions, output is modified full content OR search-like if line_numbers/only_matching and actions present (as observed)

    // Build regex for scope
    let scope_regex = if literal {
        let escaped = regex::escape(scope_pattern);
        Regex::new(&escaped).unwrap()
    } else {
        match Regex::new(scope_pattern) {
            Ok(r) => r,
            Err(_) => {
                // Invalid regex, treat as no match
                // Original would error? Let's treat as no in_scope
                return (input.to_string(), false);
            }
        }
    };

    // For language scopes, we need to compute language-filtered ranges
    // Simplified: if lang_scopes empty, language filter is whole input
    // If lang_scopes present, we need to compute intervals that are in language scope
    // Then intersect with regex scope

    // For now, implement simple heuristic language scoping for Python, Rust, etc.
    // We will have function get_lang_intervals(input, lang_scopes, join) -> Vec<(start,end)>

