    } else {
        get_lang_intervals(input, lang_scopes, join_lang)
    };

    // Now, find all regex matches within lang_intervals
    // For each lang interval, find regex matches inside

    let mut matches_in_scope: Vec<(usize, usize, Vec<(String, String)>)> = Vec::new(); // (start,end, captures)
    // For simplicity, we need to handle capture groups for replacement
    // regex::Regex provides captures

    for (lang_start, lang_end) in &lang_intervals {
        let lang_slice = &input[*lang_start..*lang_end];
        // Need to find matches with byte indices relative to lang_slice, then convert to absolute
        for mat in scope_regex.find_iter(lang_slice) {
            let start = lang_start + mat.start();
            let end = lang_start + mat.end();
            // For capture groups, we need to get captures for this match
            // We need to run captures on the slice
            // For simplicity, we will get captures for the whole input? We'll get them from regex.captures on the matched substring?
            // Actually we need to get captures for the match at that position
            // We'll use regex.captures on lang_slice[mat.start()..mat.end()]? But that would not give correct groups for patterns that include context?
            // Instead, we can get captures via regex.captures on lang_slice and find one that matches at position mat.start()
            // For simplicity, we will use scope_regex.captures on lang_slice and iterate

            // We'll collect captures for this specific match by re-running captures_iter and finding matching start
            // For now, we will just store empty captures and handle replacement later with a more precise method

            matches_in_scope.push((start, end, vec![]));
        }
    }

    // More accurate: get captures for replacement with $1, $NAME
    // We need to actually compute captures for each match
    let mut detailed_matches: Vec<(usize, usize, HashMap<String,String>)> = Vec::new();
    for (lang_start, lang_end) in &lang_intervals {
        let lang_slice = &input[*lang_start..*lang_end];
        for caps in scope_regex.captures_iter(lang_slice) {
            if let Some(m) = caps.get(0) {
                let start = lang_start + m.start();
                let end = lang_start + m.end();
                let mut map = HashMap::new();
                // Numbered groups
                for i in 0..caps.len() {
                    if let Some(c) = caps.get(i) {
                        map.insert(i.to_string(), c.as_str().to_string());
                    }
                }
                // Named groups
                for name in scope_regex.capture_names().flatten() {
                    if let Some(c) = caps.name(name) {
                        map.insert(name.to_string(), c.as_str().to_string());
                    }
                }
                detailed_matches.push((start, end, map));
            }
        }
    }

    let in_scope_found = !detailed_matches.is_empty();

    if !has_actions {
        // Search mode
        // Output search results with format: filename:line:range:content or filename:range:content depending on line_numbers etc
        // From earlier observations:
        // - If only_matching and line_numbers: filename:line:range:content (only lines with matches)
        // - If only_matching without line_numbers: filename:range:content (only lines with matches)
        // - If line_numbers without only_matching: filename:line::content for lines without matches? Actually we saw it printed all lines with empty range for non-matching.
        // - If neither line_numbers nor only_matching but search_mode (language scopes): it printed filename:line:range:content? Actually for python class alone, it printed with line numbers? We saw (stdin):1:0-15:class Foo: pass which includes line number? Actually format (stdin):1:0-15:... includes line number. So for language scope alone, it includes line numbers even without flag.

        // Let's implement:

        if !search_mode {
            // Not search mode, should have returned unchanged earlier, but we still need to return something
            return (input.to_string(), false);
        }

        // For search mode, we need to produce output per line
        let mut output = String::new();
        let lines: Vec<&str> = input.lines().collect();
        // Need to compute byte offsets for each line to map matches to lines
        let mut line_offsets: Vec<usize> = Vec::new();
        let mut offset = 0;
        for line in &lines {
            line_offsets.push(offset);
            offset += line.len() + 1; // +1 for newline, approximate (input may not end with newline)
        }

        // Group matches by line
        let mut matches_by_line: HashMap<usize, Vec<(usize, usize)>> = HashMap::new(); // line_idx -> vec<(col_start, col_end)>
        for (start, end, _) in &detailed_matches {
            // Find line index
            for (line_idx, &line_off) in line_offsets.iter().enumerate() {
                let next_off = if line_idx+1 < line_offsets.len() { line_offsets[line_idx+1] } else { input.len()+1 };
