fn normalize_transform(s: &str) -> String {
    // Simple mapping: remove diacritics via NFD stripping
    // We'll implement by replacing known accented chars with ascii equivalents
    // For simplicity, we will use a mapping table for common Latin-1
    let mut result = String::new();
    for c in s.chars() {
        let mapped = match c {
            'À'|'Á'|'Â'|'Ã'|'Ä'|'Å' => 'A',
            'à'|'á'|'â'|'ã'|'ä'|'å' => 'a',
            'Ç'|'ç' => if c.is_uppercase() {'C'} else {'c'},
            'È'|'É'|'Ê'|'Ë' => 'E',
            'è'|'é'|'ê'|'ë' => 'e',
            'Ì'|'Í'|'Î'|'Ï' => 'I',
            'ì'|'í'|'î'|'ï' => 'i',
            'Ñ' => 'N',
            'ñ' => 'n',
            'Ò'|'Ó'|'Ô'|'Õ'|'Ö' => 'O',
            'ò'|'ó'|'ô'|'õ'|'ö' => 'o',
            'Ù'|'Ú'|'Û'|'Ü' => 'U',
            'ù'|'ú'|'û'|'ü' => 'u',
            'Ý' => 'Y',
            'ý'|'ÿ' => 'y',
            _ => c,
        };
        result.push(mapped);
    }
    // Also strip combining marks if any
    // For simplicity, we keep as is, as our mapping already handles
    result
}

fn symbols_transform(s: &str) -> String {
    // Mapping table from earlier
    let mut result = s.to_string();
    // Order longest first to avoid partial replacements
    let mappings = vec![
        ("-->", "⟶"),
        ("<--", "⟵"),
        ("<->", "↔"),
        ("---", "—"),
        ("--", "–"),
        ("->", "→"),
        ("<-", "←"),
        ("=>", "⇒"),
        ("<=", "≤"),
        (">=", "≥"),
        ("!=", "≠"),
    ];
    // We need to replace all occurrences, but need to avoid overlapping replacements affecting already replaced chars
    // Simple approach: iterate and replace using a placeholder or by scanning
    // We'll implement scanning: go through string, at each position check if any mapping matches starting at that position, longest first

    let mut output = String::new();
    let chars: Vec<char> = result.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let mut matched = false;
        for (ascii, unicode) in &mappings {
            let ascii_chars: Vec<char> = ascii.chars().collect();
            if i + ascii_chars.len() <= chars.len() {
                let slice: String = chars[i..i+ascii_chars.len()].iter().collect();
                if slice == *ascii {
                    output.push_str(unicode);
                    i += ascii_chars.len();
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            output.push(chars[i]);
            i += 1;
        }
    }
    output
}

