fn has_explicit_scope_raw(args: &[String]) -> bool {
    let mut found = false;
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" { break; }
        if arg.starts_with("--") {
            let takes = is_long_takes_value(arg);
            if takes && !arg.contains('=') {
                i += 1;
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            let mut has_val = false;
            for c in arg.chars().skip(1) {
                if is_short_takes_value(c) { has_val = true; break; }
            }
            if has_val && arg.len() == 2 {
                i += 1;
            }
        } else {
            if !found { found = true; }
        }
        i += 1;
    }
    found
}
fn is_long_takes_value(arg: &str) -> bool {
    let name = arg.split('=').next().unwrap();
    matches!(name, "--completions" | "-G" | "--glob" | "--stdin-detection" | "--stdout-detection" | "--threads" | "--c" | "--c-query" | "--c-query-file" | "--csharp" | "--cs" | "--csharp-query" | "--csharp-query-file" | "--go" | "--go-query" | "--go-query-file" | "--hcl" | "--hcl-query" | "--hcl-query-file" | "--python" | "--py" | "--python-query" | "--python-query-file" | "--rust" | "--rs" | "--rust-query" | "--rust-query-file" | "--typescript" | "--ts" | "--typescript-query" | "--typescript-query-file")
}
fn is_short_takes_value(c: char) -> bool { matches!(c, 'G') }

fn process_content(
    input: &str,
    filename: &str,
    scope_pattern: &str,
    literal: bool,
    replacement: Option<String>,
    upper: bool,
    lower: bool,
    titlecase: bool,
    normalize: bool,
    german: bool,
    german_naive: bool,
    german_prefer_original: bool,
    symbols: bool,
    invert: bool,
    delete: bool,
    squeeze: bool,
    lang_scopes: &[(String, String)],
    join_lang: bool,
    line_numbers: bool,
    only_matching: bool,
    has_actions: bool,
    search_mode: bool,
) -> (String, bool) {
    let scope_regex = if literal {
        Regex::new(&regex::escape(scope_pattern)).unwrap_or_else(|_| Regex::new(".*").unwrap())
    } else {
        Regex::new(scope_pattern).unwrap_or_else(|_| Regex::new(".*").unwrap())
    };

    let lang_intervals = if lang_scopes.is_empty() {
        vec![(0, input.len())]
    } else {
        get_lang_intervals(input, lang_scopes, join_lang)
    };

    let mut detailed_matches: Vec<(usize, usize, HashMap<String,String>)> = Vec::new();
    for (ls, le) in &lang_intervals {
        let slice = &input[*ls..*le];
        for caps in scope_regex.captures_iter(slice) {
            if let Some(m) = caps.get(0) {
                let s = ls + m.start();
                let e = ls + m.end();
                let mut map = HashMap::new();
                for i in 0..caps.len() {
                    if let Some(c) = caps.get(i) {
                        map.insert(i.to_string(), c.as_str().to_string());
                    }
                }
                for name in scope_regex.capture_names().flatten() {
                    if let Some(c) = caps.name(name) {
                        map.insert(name.to_string(), c.as_str().to_string());
                    }
                }
                detailed_matches.push((s,e,map));
            }
        }
    }

    let in_scope = !detailed_matches.is_empty();

    if !has_actions {
        if !search_mode {
            return (input.to_string(), false);
        }
        let mut output = String::new();
        let lines: Vec<&str> = input.lines().collect();
        let mut line_offsets = Vec::new();
        let mut off = 0;
        for line in &lines {
            line_offsets.push(off);
            off += line.len()+1;
        }
        let mut by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
        for (s,e,_) in &detailed_matches {
            for (li, &lo) in line_offsets.iter().enumerate() {
                let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                if *s >= lo && *s < next {
                    let cs = s - lo;
                    let ce = e - lo;
                    let line_len = lines[li].len();
                    by_line.entry(li).or_default().push((std::cmp::min(cs,line_len), std::cmp::min(ce,line_len)));
                    break;
                }
            }
        }
        let show_line = line_numbers || !lang_scopes.is_empty();
        if show_line {
            if only_matching {
                for (li, cols) in &by_line {
                    let range_str = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                    output.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, range_str, lines[*li]));
                }
            } else {
                for (li, line) in lines.iter().enumerate() {
                    if let Some(cols) = by_line.get(&li) {
                        let range_str = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        output.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, range_str, line));
                    } else {
                        output.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                    }
                }
            }
        } else {
            if only_matching {
                for (li, cols) in &by_line {
                    let range_str = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                    output.push_str(&format!("{}:{}:{}\n", filename, range_str, lines[*li]));
                }
            } else {
                for line in &lines {
                    output.push_str(&format!("{}\n", line));
                }
            }
        }
        return (output, in_scope);
    } else {
        if delete {
            let mut result = String::new();
            let mut last = 0;
            let mut sorted = detailed_matches.clone();
            sorted.sort_by_key(|(s,_,_)| *s);
            for (s,e,_) in sorted {
                result.push_str(&input[last..s]);
                last = e;
            }
            result.push_str(&input[last..]);
            if line_numbers || only_matching {
                let mut out = String::new();
                let orig_lines: Vec<&str> = input.lines().collect();
                let mod_lines: Vec<&str> = result.lines().collect();
                let mut line_offsets = Vec::new();
                let mut off=0;
                for line in &orig_lines { line_offsets.push(off); off+=line.len()+1; }
                let mut by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
                for (s,e,_) in &detailed_matches {
                    for (li, &lo) in line_offsets.iter().enumerate() {
                        let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                        if *s >= lo && *s < next {
                            by_line.entry(li).or_default().push((s-lo, e-lo));
                            break;
                        }
                    }
                }
                if only_matching {
                    if line_numbers {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, mod_c));
                        }
                    } else {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}\n", filename, rs, mod_c));
                        }
                    }
                } else {
                    for (li, line) in mod_lines.iter().enumerate() {
                        if let Some(cols) = by_line.get(&li) {
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, line));
                        } else {
                            out.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                        }
                    }
                }
                return (out, in_scope);
            }
            return (result, in_scope);
        }
        if squeeze {
            let mut result = String::new();
            let mut last_end = 0;
            let mut sorted = detailed_matches.clone();
            sorted.sort_by_key(|(s,_,_)| *s);
            let mut prev_end = None;
            for (s,e,_) in sorted {
                result.push_str(&input[last_end..s]);
                if let Some(pe) = prev_end {
                    if s == pe {
                        // skip
                    } else {
                        result.push_str(&input[s..e]);
                        prev_end = Some(e);
                    }
                } else {
                    result.push_str(&input[s..e]);
                    prev_end = Some(e);
                }
                last_end = e;
            }
            result.push_str(&input[last_end..]);
            if line_numbers || only_matching {
                let mut out = String::new();
                let orig_lines: Vec<&str> = input.lines().collect();
                let mod_lines: Vec<&str> = result.lines().collect();
                let mut line_offsets = Vec::new();
                let mut off=0;
                for line in &orig_lines { line_offsets.push(off); off+=line.len()+1; }
                let mut by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
                for (s,e,_) in &detailed_matches {
                    for (li, &lo) in line_offsets.iter().enumerate() {
                        let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                        if *s >= lo && *s < next {
                            by_line.entry(li).or_default().push((s-lo, e-lo));
                            break;
                        }
                    }
                }
                if only_matching {
                    if line_numbers {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, mod_c));
                        }
                    } else {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}\n", filename, rs, mod_c));
                        }
                    }
                } else {
                    for (li, line) in mod_lines.iter().enumerate() {
                        if let Some(cols) = by_line.get(&li) {
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, line));
                        } else {
                            out.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                        }
                    }
                }
                return (out, in_scope);
            }
            return (result, in_scope);
        }

        let mut sorted = detailed_matches.clone();
        sorted.sort_by_key(|(s,_,_)| *s);
        let mut result = String::new();
        let mut last_end = 0;
        let mut adjusted_by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
        let mut line_offsets = Vec::new();
        {
            let lines: Vec<&str> = input.lines().collect();
            let mut off=0;
            for line in &lines { line_offsets.push(off); off+=line.len()+1; }
        }
        let mut delta: isize = 0;
        for (s,e,caps) in &sorted {
            result.push_str(&input[last_end..*s]);
            let mut seg = input[*s..*e].to_string();
            if let Some(rep) = &replacement {
                seg = expand_replacement(rep, caps.clone());
            }
            if upper { seg = seg.to_uppercase(); }
            if lower { seg = seg.to_lowercase(); }
            if titlecase { seg = titlecase_transform(&seg); }
            if normalize { seg = normalize_transform(&seg); }
            if symbols {
                if invert { seg = symbols_invert(&seg); } else { seg = symbols_transform(&seg); }
            }
            if german {
                seg = german_transform(&seg, german_naive, german_prefer_original, invert && !symbols);
            }
            let new_len = seg.len() as isize;
            let orig_len = (*e as isize - *s as isize);
            // compute line for adjusted
            for (li, &lo) in line_offsets.iter().enumerate() {
                let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                if *s >= lo && *s < next {
                    let cs = (*s - lo) as isize + delta;
                    let ce = cs + new_len;
                    adjusted_by_line.entry(li).or_default().push((cs as usize, ce as usize));
                    break;
                }
            }
            delta += new_len - orig_len;
            result.push_str(&seg);
            last_end = *e;
        }
        result.push_str(&input[last_end..]);

        if line_numbers || only_matching {
            let mut out = String::new();
            let mod_lines: Vec<&str> = result.lines().collect();
            if only_matching {
                if line_numbers {
                    for (li, cols) in &adjusted_by_line {
                        let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                        let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, mod_c));
                    }
                } else {
                    for (li, cols) in &adjusted_by_line {
                        let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                        let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        out.push_str(&format!("{}:{}:{}\n", filename, rs, mod_c));
                    }
                }
            } else {
                for (li, line) in mod_lines.iter().enumerate() {
                    if let Some(cols) = adjusted_by_line.get(&li) {
                        let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, line));
                    } else {
                        out.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                    }
                }
            }
            return (out, in_scope);
        }

        return (result, in_scope);
    }
}

fn expand_replacement(rep: &str, caps: HashMap<String,String>) -> String {
    let mut result = String::new();
    let mut chars = rep.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '$' {
            if let Some(&next) = chars.peek() {
                if next == '$' {
                    result.push('$'); chars.next();
                } else if next.is_ascii_digit() {
                    let mut num = String::new();
                    while let Some(&d) = chars.peek() {
                        if d.is_ascii_digit() { num.push(d); chars.next(); } else { break; }
                    }
                    if let Some(v) = caps.get(&num) { result.push_str(v); }
                } else if next == '{' {
                    chars.next();
                    let mut name = String::new();
                    while let Some(ch) = chars.next() {
                        if ch == '}' { break; } else { name.push(ch); }
                    }
                    if let Some(v) = caps.get(&name) { result.push_str(v); }
                } else if next.is_alphabetic() || next == '_' {
                    let mut name = String::new();
                    while let Some(&ch) = chars.peek() {
                        if ch.is_alphanumeric() || ch == '_' { name.push(ch); chars.next(); } else { break; }
                    }
                    if let Some(v) = caps.get(&name) { result.push_str(v); }
                } else {
                    result.push('$');
                }
            } else {
                result.push('$');
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn titlecase_transform(s: &str) -> String {
    // Simplified titlecase that matches earlier approximation
    // We'll reuse logic from earlier that passed most tests
    let delims: Vec<char> = vec![',','/','-',';','!','?','{','}','"','#','$','%','^','*','+','=','<','>','|','\\','`','~'];
    let delims_set: std::collections::HashSet<char> = delims.into_iter().collect();

    // Split by whitespace preserving
    let re_ws = Regex::new(r"(\s+)").unwrap();
    let ws_parts: Vec<&str> = re_ws.split(s).collect();
    let ws_seps: Vec<&str> = re_ws.find_iter(s).map(|m| m.as_str()).collect();

    // Collect all subwords for case analysis
    let mut all_words: Vec<String> = Vec::new();
    for part in re_ws.split(s) {
        if part.trim().is_empty() { continue; }
        // split by delims
        let mut current = String::new();
        for ch in part.chars() {
            if delims_set.contains(&ch) {
                if !current.is_empty() { all_words.push(current.clone()); current.clear(); }
            } else {
                current.push(ch);
            }
        }
        if !current.is_empty() { all_words.push(current); }
    }

    let mut has_lower = false;
    let mut has_upper = false;
    let mut has_mixed = false;
    for w in &all_words {
        if w.chars().all(|c| !c.is_alphabetic()) { continue; }
        let is_lower = w.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_lowercase());
        let is_upper = w.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_uppercase());
        if is_lower { has_lower = true; }
        else if is_upper { has_upper = true; }
        else {
            // Check if title
            let mut chars = w.chars().filter(|c| c.is_alphabetic());
            if let Some(first) = chars.next() {
                if first.is_uppercase() && chars.clone().all(|c| c.is_lowercase()) {
                    // title
                } else {
                    has_mixed = true;
                }
            } else {
                has_mixed = true;
            }
        }
    }

    let convert_lower = if has_lower { true } else { false };
    let convert_upper = if !has_lower && !has_mixed && has_upper { true } else { false };

    // Now transform
    let mut result = String::new();
    let mut parts_iter = re_ws.split(s);
    let mut sep_iter = re_ws.find_iter(s).map(|m| m.as_str());
    // We need to interleave
    // re.split gives parts including empty? Let's use manual
    let mut last_end = 0;
    let ws_re = Regex::new(r"\s+").unwrap();
    let mut result2 = String::new();
    let mut last = 0;
    for m in ws_re.find_iter(s) {
        let start = m.start();
        let end = m.end();
        let token = &s[last..start];
        if !token.is_empty() {
            result2.push_str(&transform_token(token, &delims_set, convert_lower, convert_upper));
        }
        result2.push_str(m.as_str());
        last = end;
    }
    let token = &s[last..];
    if !token.is_empty() {
        result2.push_str(&transform_token(token, &delims_set, convert_lower, convert_upper));
    }
    result2
}

fn transform_token(token: &str, delims_set: &std::collections::HashSet<char>, convert_lower: bool, convert_upper: bool) -> String {
    let mut out = String::new();
    let mut current = String::new();
    for ch in token.chars() {
        if delims_set.contains(&ch) {
            if !current.is_empty() {
                out.push_str(&transform_word(&current, convert_lower, convert_upper));
                current.clear();
            }
            out.push(ch);
        } else {
            current.push(ch);
        }
    }
    if !current.is_empty() {
        out.push_str(&transform_word(&current, convert_lower, convert_upper));
    }
    out
}

fn transform_word(word: &str, convert_lower: bool, convert_upper: bool) -> String {
    // Classify word
    let cased: Vec<char> = word.chars().filter(|c| c.is_alphabetic()).collect();
    if cased.is_empty() { return word.to_string(); }
    let is_lower = cased.iter().all(|c| c.is_lowercase());
    let is_upper = cased.iter().all(|c| c.is_uppercase());
    let is_title = {
        if let Some(first) = cased.first() {
            first.is_uppercase() && cased.iter().skip(1).all(|c| c.is_lowercase())
        } else { false }
    };
    if is_lower && convert_lower {
        // Titlecase: first alpha upper, rest lower
        let mut chars: Vec<char> = word.chars().collect();
        let mut first_found = false;
        for i in 0..chars.len() {
            if chars[i].is_alphabetic() {
                if !first_found {
                    chars[i] = chars[i].to_uppercase().next().unwrap_or(chars[i]);
                    first_found = true;
                } else {
                    chars[i] = chars[i].to_lowercase().next().unwrap_or(chars[i]);
                }
            }
        }
        chars.into_iter().collect()
    } else if is_upper && convert_upper {
        let mut chars: Vec<char> = word.chars().collect();
        let mut first_found = false;
        for i in 0..chars.len() {
            if chars[i].is_alphabetic() {
                if !first_found {
                    chars[i] = chars[i].to_uppercase().next().unwrap_or(chars[i]);
                    first_found = true;
                } else {
                    chars[i] = chars[i].to_lowercase().next().unwrap_or(chars[i]);
                }
            }
        }
        chars.into_iter().collect()
    } else {
        word.to_string()
    }
}

fn normalize_transform(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        let mapped = match c {
            'À'|'Á'|'Â'|'Ã'|'Ä'|'Å' => 'A',
            'à'|'á'|'â'|'ã'|'ä'|'å' => 'a',
            'Ç' => 'C', 'ç' => 'c',
            'È'|'É'|'Ê'|'Ë' => 'E',
            'è'|'é'|'ê'|'ë' => 'e',
            'Ì'|'Í'|'Î'|'Ï' => 'I',
            'ì'|'í'|'î'|'ï' => 'i',
            'Ñ' => 'N', 'ñ' => 'n',
            'Ò'|'Ó'|'Ô'|'Õ'|'Ö' => 'O',
            'ò'|'ó'|'ô'|'õ'|'ö' => 'o',
            'Ù'|'Ú'|'Û'|'Ü' => 'U',
            'ù'|'ú'|'û'|'ü' => 'u',
            'Ý' => 'Y', 'ý'|'ÿ' => 'y',
            'ß' => 's', 'ẞ' => 'S',
            _ => c,
        };
        result.push(mapped);
    }
    result
}

fn symbols_transform(s: &str) -> String {
    let mappings = vec![
        ("-->", "⟶"),
        ("<--", "⟵"),
        ("<->", "↔"),
        ("---", "—"),
        ("--", "–"),
        ("->", "→"),
        ("<-", "←"),
        ("=>", "⇒"),
        ("<=", "≤"),
        (">=", "≥"),
        ("!=", "≠"),
    ];
    let mut out = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let mut matched = false;
        for (a,u) in &mappings {
            let ac: Vec<char> = a.chars().collect();
            if i+ac.len() <= chars.len() {
                let slice: String = chars[i..i+ac.len()].iter().collect();
                if slice == *a {
                    out.push_str(u);
                    i+=ac.len();
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            out.push(chars[i]);
            i+=1;
        }
    }
    out
}

fn symbols_invert(s: &str) -> String {
    let mappings = vec![
        ("⟶", "-->"),
        ("⟵", "<--"),
        ("↔", "<->"),
        ("—", "---"),
        ("–", "--"),
        ("→", "->"),
        ("←", "<-"),
        ("⇒", "=>"),
        ("≤", "<="),
        ("≥", ">="),
        ("≠", "!="),
    ];
    let mut out = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let mut matched = false;
        for (u,a) in &mappings {
            let uc: Vec<char> = u.chars().collect();
            if i+uc.len() <= chars.len() {
                let slice: String = chars[i..i+uc.len()].iter().collect();
                if slice == *u {
                    out.push_str(a);
                    i+=uc.len();
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            out.push(chars[i]);
            i+=1;
        }
    }
    out
}

fn german_transform(s: &str, naive: bool, prefer_original: bool, _invert: bool) -> String {
    if prefer_original {
        let lower = s.to_lowercase();
        if lower == "busse" || lower == "masse" || lower == "strasse" || lower == "buße" || lower == "maße" || lower == "straße" {
            if lower == "busse" || lower == "masse" || lower == "strasse" {
                return s.to_string();
            }
        }
    }
    let mappings = vec![
        ("AE", "Ä"), ("Ae", "Ä"), ("ae", "ä"),
        ("OE", "Ö"), ("Oe", "Ö"), ("oe", "ö"),
        ("UE", "Ü"), ("Ue", "Ü"), ("ue", "ü"),
        ("SS", "ẞ"), ("Ss", "ẞ"), ("ss", "ß"),
    ];
    let mut out = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let mut matched = false;
        for (a,u) in &mappings {
            let ac: Vec<char> = a.chars().collect();
            if i+ac.len() <= chars.len() {
                let slice: String = chars[i..i+ac.len()].iter().collect();
                if slice == *a {
                    if !naive {
                        let low_a = a.to_lowercase();
                        if low_a == "ue" {
                            if i>0 {
                                let prev = chars[i-1].to_lowercase().to_string();
                                if prev == "a" || prev == "e" {
                                    if i+ac.len() < chars.len() {
                                        let next = chars[i+ac.len()].to_lowercase().to_string();
                                        if next == "r" || next == "n" {
                                            continue;
                                        }
                                    }
                                }
                            }
                        }
                        if low_a == "oe" {
                            if i>0 {
                                let prev = chars[i-1].to_lowercase().to_string();
                                if prev == "o" {
                                    continue;
                                }
                            }
                        }
                    }
                    out.push_str(u);
                    i+=ac.len();
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            out.push(chars[i]);
            i+=1;
        }
    }
    out
}

fn get_lang_intervals(input: &str, lang_scopes: &[(String,String)], join: bool) -> Vec<(usize,usize)> {
    let mut intervals: Vec<(usize,usize)> = Vec::new();
    for (lang, query) in lang_scopes {
        let cur = match lang.as_str() {
            "python" | "py" => get_python_intervals(input, query),
            "rust" | "rs" => get_rust_intervals(input, query),
            "go" => get_go_intervals(input, query),
            "typescript" | "ts" => get_typescript_intervals(input, query),
            "c" => get_c_intervals(input, query),
            "csharp" | "cs" => get_csharp_intervals(input, query),
            "hcl" => get_hcl_intervals(input, query),
            _ => vec![(0, input.len())],
        };
        if intervals.is_empty() {
            intervals = cur;
        } else {
            if join {
                intervals.extend(cur);
                intervals = merge_intervals(intervals);
            } else {
                intervals = intersect_intervals(&intervals, &cur);
            }
        }
    }
    if intervals.is_empty() { vec![(0, input.len())] } else { intervals }
}

fn merge_intervals(mut intervals: Vec<(usize,usize)>) -> Vec<(usize,usize)> {
    if intervals.is_empty() { return intervals; }
    intervals.sort_by_key(|(s,_)| *s);
    let mut merged = vec![intervals[0]];
    for (s,e) in intervals.into_iter().skip(1) {
        let last = merged.last_mut().unwrap();
        if s <= last.1 { last.1 = last.1.max(e); } else { merged.push((s,e)); }
    }
    merged
}

fn intersect_intervals(a: &[(usize,usize)], b: &[(usize,usize)]) -> Vec<(usize,usize)> {
    let mut res = Vec::new();
    for (s1,e1) in a {
        for (s2,e2) in b {
            let s = (*s1).max(*s2);
            let e = (*e1).min(*e2);
            if s < e { res.push((s,e)); }
        }
    }
    merge_intervals(res)
}

fn get_python_intervals(input: &str, query: &str) -> Vec<(usize,usize)> {
    match query {
        "comments" => {
            let re = Regex::new(r"#.*").unwrap();
            re.find_iter(input).map(|m| (m.start(), m.end())).collect()
        },
        "strings" => {
            let re = Regex::new(r#""[^"]*"|'[^']*'"#).unwrap();
            re.find_iter(input).map(|m| (m.start(), m.end())).collect()
        },
        "class" => {
            let re = Regex::new(r"(?m)^class\s+\w+.*:\n(?:[ \t]+.*\n?)*").unwrap();
            let mut v: Vec<(usize,usize)> = re.find_iter(input).map(|m| (m.start(), m.end())).collect();
            if v.is_empty() {
                let re2 = Regex::new(r"(?m)^.*class.*$").unwrap();
                v = re2.find_iter(input).map(|m| (m.start(), m.end())).collect();
            }
            if v.is_empty() { vec![(0, input.len())] } else { v }
        },
        "def" => {
            let re = Regex::new(r"(?m)^ *def\s+\w+.*:\n(?:[ \t]+.*\n?)*").unwrap();
            let mut v: Vec<(usize,usize)> = re.find_iter(input).map(|m| (m.start(), m.end())).collect();
            if v.is_empty() {
                let re2 = Regex::new(r"(?m)^.*def.*$").unwrap();
                v = re2.find_iter(input).map(|m| (m.start(), m.end())).collect();
            }
            if v.is_empty() { vec![(0, input.len())] } else { v }
        },
        _ => vec![(0, input.len())],
    }
}
fn get_rust_intervals(input: &str, _query: &str) -> Vec<(usize,usize)> { vec![(0, input.len())] }
fn get_go_intervals(input: &str, _query: &str) -> Vec<(usize,usize)> { vec![(0, input.len())] }
fn get_typescript_intervals(input: &str, _query: &str) -> Vec<(usize,usize)> { vec![(0, input.len())] }
fn get_c_intervals(input: &str, _query: &str) -> Vec<(usize,usize)> { vec![(0, input.len())] }
fn get_csharp_intervals(input: &str, _query: &str) -> Vec<(usize,usize)> { vec![(0, input.len())] }
fn get_hcl_intervals(input: &str, _query: &str) -> Vec<(usize,usize)> { vec![(0, input.len())] }

fn get_ranges_for_line(line: &str, scope_pattern: &str, literal: bool) -> Vec<(usize,usize)> {
    let re = if literal {
        Regex::new(&regex::escape(scope_pattern)).unwrap_or_else(|_| Regex::new(".*").unwrap())
    } else {
        Regex::new(scope_pattern).unwrap_or_else(|_| Regex::new(".*").unwrap())
    };
    re.find_iter(line).map(|m| (m.start(), m.end())).collect()
}

fn build_cli() -> Command {
    Command::new("srgn")
        .version("0.14.1")
        .about("A grep-like tool which understands source code syntax and allows for manipulation in addition to search")
        .arg(Arg::new("SCOPE").help("Scope to apply to, as a regular expression pattern.\n\nIf string literal mode is requested, will be interpreted as a literal string.\n\nActions will apply their transformations within this scope only.\n\nThe default is the global scope, matching the entire input. Where that default is meaningless or dangerous (e.g., deletion), this argument is required.\n\n[default: .*]").default_value(".*"))
        .arg(Arg::new("REPLACEMENT").help("Replace anything in scope with this value.\n\nVariables are supported: if a regex pattern was used for scoping and captured content in named or numbered capture groups, access these in the replacement value using `$1` etc. for numbered, `$NAME` etc. for named capture groups.\n\nThis action is specially treated as a positional argument for ergonomics and compatibility with `tr`.\n\nIf given, will run before any other action.\n\n[env: REPLACE=]").value_name("REPLACEMENT").last(true).env("REPLACE"))
        .arg(Arg::new("completions").long("completions").value_name("SHELL").help("Print shell completions for the given shell.\n\n[possible values: bash, elvish, fish, powershell, zsh]").value_parser(["bash","elvish","fish","powershell","zsh"]))
        .arg(Arg::new("upper").short('u').long("upper").help("Uppercase anything in scope.\n\n[env: UPPER=]").action(ArgAction::SetTrue).env("UPPER").value_parser(value_parser!(bool)))
        .arg(Arg::new("lower").short('l').long("lower").help("Lowercase anything in scope.\n\n[env: LOWER=]").action(ArgAction::SetTrue).env("LOWER").value_parser(value_parser!(bool)))
        .arg(Arg::new("titlecase").short('t').long("titlecase").help("Titlecase anything in scope.\n\n[env: TITLECASE=]").action(ArgAction::SetTrue).env("TITLECASE").value_parser(value_parser!(bool)))
        .arg(Arg::new("normalize").short('n').long("normalize").help("Normalize (Normalization Form D) anything in scope, and throw away marks.\n\n[env: NORMALIZE=]").action(ArgAction::SetTrue).env("NORMALIZE").value_parser(value_parser!(bool)))
        .arg(Arg::new("german").short('g').long("german").help("Perform substitutions on German words, such as 'Abenteuergruesse' to 'Abenteuergrüße', for anything in scope.\n\nASCII spellings for Umlauts (ae, oe, ue) and Eszett (ss) are replaced by their respective native Unicode (ä, ö, ü, ß).\n\nArbitrary compound words are supported.\n\nWords legally containing alternative spellings are not modified.\n\nWords require correct spelling to be detected.").action(ArgAction::SetTrue).env("GERMAN").value_parser(value_parser!(bool)))
        .arg(Arg::new("symbols").short('S').long("symbols").help("Perform substitutions on symbols, such as '!=' to '≠', '->' to '→', on anything in scope.\n\nHelps translate 'ASCII art' into native Unicode representations.").action(ArgAction::SetTrue))
        .arg(Arg::new("delete").short('d').long("delete").help("Delete anything in scope.\n\nCannot be used with any other action: there is no point in deleting and performing any other processing. Sibling actions would either receive empty input or have their work wiped.").action(ArgAction::SetTrue))
        .arg(Arg::new("squeeze").short('s').long("squeeze").aliases(["squeeze-repeats"]).help("Squeeze consecutive occurrences of scope into one.\n\n[env: SQUEEZE=]\n[aliases: squeeze-repeats]").action(ArgAction::SetTrue).env("SQUEEZE").value_parser(value_parser!(bool)))
        .arg(Arg::new("glob").short('G').long("glob").value_name("GLOB").help("Glob of files to work on (instead of reading stdin).\n\nIf actions are applied, they overwrite files in-place.\n\nFor supported glob syntax, see:\n<https://docs.rs/glob/0.3.1/glob/struct.Pattern.html>\n\nNames of processed files are written to stdout.").action(ArgAction::Append))
        .arg(Arg::new("fail-no-files").long("fail-no-files").help("Fail if working on files (e.g. globbing is requested) but none are found.\n\nProcessing no files is not an error condition in itself, but might be an unexpected outcome in some contexts. This flag makes the condition explicit.").action(ArgAction::SetTrue))
        .arg(Arg::new("dry-run").long("dry-run").help("Do not destructively overwrite files, instead print rich diff only.\n\nThe diff details the names of files which would be modified, alongside all changes inside those files which would be performed outside of dry running. It is similar to git diff with word diffing enabled.").action(ArgAction::SetTrue))
        .arg(Arg::new("invert").short('i').long("invert").help("Undo the effects of passed actions, where applicable.\n\nRequires a 1:1 mapping between replacements and original, which is currently available only for:\n\n- symbols: '≠' <-> '!=' etc.\n\nOther actions:\n\n- german: inverting e.g. 'Ä' is ambiguous (can be 'Ae' or 'AE')\n\n- upper, lower, deletion, squeeze: inversion is impossible as information is lost\n\nThese may still be passed, but will be ignored for inversion and applied normally.\n\n[env: INVERT=]").action(ArgAction::SetTrue).env("INVERT").value_parser(value_parser!(bool)))
        .arg(Arg::new("literal-string").short('L').long("literal-string").help("Do not interpret the scope as a regex. Instead, interpret it as a literal string. Will require a scope to be passed.\n\n[env: LITERAL_STRING=]").action(ArgAction::SetTrue).env("LITERAL_STRING").value_parser(value_parser!(bool)))
        .arg(Arg::new("fail-any").long("fail-any").help("If anything at all is found to be in scope, fail.\n\nThe default is to continue processing normally.").action(ArgAction::SetTrue))
        .arg(Arg::new("fail-none").long("fail-none").help("If nothing is found to be in scope, fail.\n\nThe default is to return the input unchanged (without failure).").action(ArgAction::SetTrue))
        .arg(Arg::new("join-language-scopes").short('j').long("join-language-scopes").help("Join (logical 'OR') multiple language scopes, instead of intersecting them.\n\nThe default when multiple language scopes are given is to intersect their scopes, left to right. For example, `--go func --go strings` will first scope down to `func` bodies, then look for strings only within those. This flag instead joins (in the set logic sense) all scopes. The example would then scope any `func` bodies, and any strings, anywhere. Language scopers can then also be given in any order.\n\nNo effect if only a single language scope is given. Also does not affect non-language scopers (regex pattern etc.), which always intersect.").action(ArgAction::SetTrue))
        .arg(Arg::new("hidden").short('H').long("hidden").help("Do not ignore hidden files and directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("gitignored").long("gitignored").help("Do not ignore `.gitignore`d files and directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("sorted").long("sorted").help("Process files in lexicographically sorted order, by file path.\n\nIn search mode, this emits results in sorted order. Otherwise, it processes files in sorted order.\n\nSorted processing disables parallel processing.").action(ArgAction::SetTrue))
        .arg(Arg::new("stdin-detection").long("stdin-detection").value_name("STDIN_DETECTION").help("Control heuristics for stdin readability detection, and force to value.\n\n[default: auto]").default_value("auto").value_parser(["auto","force-readable","force-unreadable"]))
        .arg(Arg::new("stdout-detection").long("stdout-detection").value_name("STDOUT_DETECTION").help("Control heuristics for stdout detection, and potentially force to value.\n\n[default: auto]").default_value("auto").value_parser(["auto","force-tty","force-pipe"]))
        .arg(Arg::new("threads").long("threads").value_name("THREADS").help("Number of threads to run processing on, when working with files.\n\nIf not specified, will default to available parallelism. Set to 1 for sequential, deterministic (but not sorted) output."))
        .arg(Arg::new("verbose").short('v').long("verbose").help("Increase log verbosity level.\n\nThe base log level to use is read from the `RUST_LOG` environment variable (if unspecified, defaults to 'error'), and increased according to the number of times this flag is given, maxing out at 'trace' verbosity.").action(ArgAction::Count))
        .arg(Arg::new("line-numbers").long("line-numbers").action(ArgAction::SetTrue))
        .arg(Arg::new("only-matching").long("only-matching").action(ArgAction::SetTrue))
        .arg(Arg::new("c").long("c").value_name("C").env("C").action(ArgAction::Append))
        .arg(Arg::new("c-query").long("c-query").value_name("TREE-SITTER-QUERY-VALUE").env("C_QUERY").action(ArgAction::Append))
        .arg(Arg::new("c-query-file").long("c-query-file").value_name("TREE-SITTER-QUERY-FILENAME").env("C_QUERY_FILE").action(ArgAction::Append))
        .arg(Arg::new("csharp").long("csharp").alias("cs").value_name("CSHARP").env("CSHARP").action(ArgAction::Append))
        .arg(Arg::new("csharp-query").long("csharp-query").value_name("TREE-SITTER-QUERY-VALUE").env("CSHARP_QUERY").action(ArgAction::Append))
        .arg(Arg::new("csharp-query-file").long("csharp-query-file").value_name("TREE-SITTER-QUERY-FILENAME").env("CSHARP_QUERY_FILE").action(ArgAction::Append))
        .arg(Arg::new("go").long("go").value_name("GO").env("GO").action(ArgAction::Append))
        .arg(Arg::new("go-query").long("go-query").value_name("TREE-SITTER-QUERY-VALUE").env("GO_QUERY").action(ArgAction::Append))
        .arg(Arg::new("go-query-file").long("go-query-file").value_name("TREE-SITTER-QUERY-FILENAME").env("GO_QUERY_FILE").action(ArgAction::Append))
        .arg(Arg::new("hcl").long("hcl").value_name("HCL").env("HCL").action(ArgAction::Append))
        .arg(Arg::new("hcl-query").long("hcl-query").value_name("TREE-SITTER-QUERY-VALUE").env("HCL_QUERY").action(ArgAction::Append))
        .arg(Arg::new("hcl-query-file").long("hcl-query-file").value_name("TREE-SITTER-QUERY-FILENAME").env("HCL_QUERY_FILE").action(ArgAction::Append))
        .arg(Arg::new("python").long("python").alias("py").value_name("PYTHON").env("PYTHON").action(ArgAction::Append))
        .arg(Arg::new("python-query").long("python-query").value_name("TREE-SITTER-QUERY-VALUE").env("PYTHON_QUERY").action(ArgAction::Append))
        .arg(Arg::new("python-query-file").long("python-query-file").value_name("TREE-SITTER-QUERY-FILENAME").env("PYTHON_QUERY_FILE").action(ArgAction::Append))
        .arg(Arg::new("rust").long("rust").alias("rs").value_name("RUST").env("RUST").action(ArgAction::Append))
        .arg(Arg::new("rust-query").long("rust-query").value_name("TREE-SITTER-QUERY-VALUE").env("RUST_QUERY").action(ArgAction::Append))
        .arg(Arg::new("rust-query-file").long("rust-query-file").value_name("TREE-SITTER-QUERY-FILENAME").env("RUST_QUERY_FILE").action(ArgAction::Append))
        .arg(Arg::new("typescript").long("typescript").alias("ts").value_name("TYPESCRIPT").env("TYPESCRIPT").action(ArgAction::Append))
        .arg(Arg::new("typescript-query").long("typescript-query").value_name("TREE-SITTER-QUERY-VALUE").env("TYPESCRIPT_QUERY").action(ArgAction::Append))
        .arg(Arg::new("typescript-query-file").long("typescript-query-file").value_name("TREE-SITTER-QUERY-FILENAME").env("TYPESCRIPT_QUERY_FILE").action(ArgAction::Append))
        .arg(Arg::new("german-prefer-original").long("german-prefer-original").env("GERMAN_PREFER_ORIGINAL").action(ArgAction::SetTrue))
        .arg(Arg::new("german-naive").long("german-naive").env("GERMAN_NAIVE").action(ArgAction::SetTrue))
}
RS
cargo build --offline 2>&1 | tail -n 30
