    }
    collect_lang!("c", "c");
    collect_lang!("c-query", "c-query");
    collect_lang!("c-query-file", "c-query-file");
    collect_lang!("csharp", "csharp");
    collect_lang!("csharp-query", "csharp-query");
    collect_lang!("csharp-query-file", "csharp-query-file");
    collect_lang!("go", "go");
    collect_lang!("go-query", "go-query");
    collect_lang!("go-query-file", "go-query-file");
