        let mut files: Vec<PathBuf> = Vec::new();
        if !glob_patterns.is_empty() {
            for pat in &glob_patterns {
                match glob(pat) {
                    Ok(paths) => {
                        for entry in paths {
                            match entry {
                                Ok(p) => files.push(p),
                                Err(e) => { eprintln!("Error: {:?}", e); }
                            }
                        }
                    }
                    Err(e) => { eprintln!("Error: {:?}", e); }
                }
            }
        } else {
            if has_lang {
                let walker = ignore::WalkBuilder::new(".")
                    .hidden(!hidden)
                    .git_ignore(!gitignored)
                    .git_global(!gitignored)
                    .git_exclude(!gitignored)
                    .build();
                for result in walker {
                    if let Ok(entry) = result {
                        let path = entry.path();
                        if path.is_file() {
                            if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
                                let include = lang_scopes.iter().any(|(lang,_)| {
                                    match lang.as_str() {
                                        "python" | "py" => ext == "py",
                                        "rust" | "rs" => ext == "rs",
                                        "go" => ext == "go",
                                        "typescript" | "ts" => ext == "ts" || ext == "tsx",
                                        "c" => ext == "c" || ext == "h",
                                        "csharp" | "cs" => ext == "cs",
                                        "hcl" => ext == "hcl" || ext == "tf",
                                        _ => false,
                                    }
                                });
                                if include {
                                    files.push(path.to_path_buf());
                                }
                            }
                        }
                    }
                }
            }
        }

        if sorted {
            files.sort();
        }

        if files.is_empty() {
            if fail_no_files {
                eprintln!("Error: No files found");
                std::process::exit(1);
            } else {
                return;
            }
        }

        let mut any_in_scope = false;
        for file_path in &files {
            let content = match fs::read_to_string(file_path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let (output, in_scope_found) = process_content(
                &content,
                &file_path.display().to_string(),
                &scope_pattern,
                literal_string,
                replacement.clone(),
                upper,
                lower,
                titlecase,
                normalize,
                german,
                german_naive,
                german_prefer_original,
                symbols,
                invert,
                delete,
                squeeze,
                &lang_scopes,
                join_lang,
                line_numbers,
                only_matching,
                has_actions,
                search_mode,
            );

            if in_scope_found {
                any_in_scope = true;
            }

            if has_actions {
                if dry_run {
                    if output != content && in_scope_found {
                        let orig_lines: Vec<&str> = content.lines().collect();
                        let mod_lines: Vec<&str> = output.lines().collect();
                        for (idx, (orig_line, mod_line)) in orig_lines.iter().zip(mod_lines.iter()).enumerate() {
                            if orig_line != mod_line {
                                let ranges_orig = get_ranges_for_line(orig_line, &scope_pattern, literal_string);
                                let ranges_mod = get_ranges_for_line(mod_line, &scope_pattern, literal_string);
                                let range_str_orig = ranges_orig.iter().map(|(s,e)| format!("{}-{}", s, e)).collect::<Vec<_>>().join(";");
                                let range_str_mod = ranges_mod.iter().map(|(s,e)| format!("{}-{}", s, e)).collect::<Vec<_>>().join(";");
                                println!("{}:{}:{}:{}", file_path.display(), idx+1, range_str_orig, orig_line);
                                println!("{}:{}:{}:{}", file_path.display(), idx+1, range_str_mod, mod_line);
                            }
                        }
                    }
                } else {
                    if in_scope_found && output != content {
                        let _ = fs::write(file_path, output);
                        println!("{}", file_path.display());
                    } else if in_scope_found && (delete || squeeze) && output != content {
                        let _ = fs::write(file_path, output);
                        println!("{}", file_path.display());
                    } else if in_scope_found && output == content {
                        // Even if no change but in scope, should we print? For replacement with same content? Original prints filename if in scope? Let's check: if replacement same as original, does it count as modified? Probably not.
                        // For simplicity, if in_scope_found and output != content, print, else if delete/squeeze and output != content?
                    }
                }
            } else {
                if in_scope_found {
                    print!("{}", output);
                }
            }
        }

        if fail_any && any_in_scope {
            eprintln!("Error: Error applying: Some input was in scope");
            std::process::exit(1);
        }
        if fail_none && !any_in_scope {
            eprintln!("Error: Error applying: No input was in scope");
            std::process::exit(1);
        }
    }
}

fn has_explicit_scope_raw(args: &[String]) -> bool {
    let mut found = false;
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" { break; }
        if arg.starts_with("--") {
            let takes = is_long_takes_value(arg);
            if takes && !arg.contains('=') {
                i += 1;
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            let mut has_val = false;
            for c in arg.chars().skip(1) {
                if is_short_takes_value(c) { has_val = true; break; }
            }
            if has_val && arg.len() == 2 {
                i += 1;
            }
        } else {
            if !found { found = true; }
        }
        i += 1;
    }
    found
}
fn is_long_takes_value(arg: &str) -> bool {
    let name = arg.split('=').next().unwrap();
    matches!(name, "--completions" | "-G" | "--glob" | "--stdin-detection" | "--stdout-detection" | "--threads" | "--c" | "--c-query" | "--c-query-file" | "--csharp" | "--cs" | "--csharp-query" | "--csharp-query-file" | "--go" | "--go-query" | "--go-query-file" | "--hcl" | "--hcl-query" | "--hcl-query-file" | "--python" | "--py" | "--python-query" | "--python-query-file" | "--rust" | "--rs" | "--rust-query" | "--rust-query-file" | "--typescript" | "--ts" | "--typescript-query" | "--typescript-query-file")
}
fn is_short_takes_value(c: char) -> bool { matches!(c, 'G') }

fn process_content(
    input: &str,
    filename: &str,
    scope_pattern: &str,
    literal: bool,
    replacement: Option<String>,
    upper: bool,
    lower: bool,
    titlecase: bool,
    normalize: bool,
    german: bool,
    german_naive: bool,
    german_prefer_original: bool,
    symbols: bool,
    invert: bool,
    delete: bool,
    squeeze: bool,
    lang_scopes: &[(String, String)],
    join_lang: bool,
    line_numbers: bool,
    only_matching: bool,
    has_actions: bool,
    search_mode: bool,
) -> (String, bool) {
    let scope_regex = if literal {
        Regex::new(&regex::escape(scope_pattern)).unwrap_or_else(|_| Regex::new(".*").unwrap())
    } else {
        Regex::new(scope_pattern).unwrap_or_else(|_| Regex::new(".*").unwrap())
    };

    let lang_intervals = if lang_scopes.is_empty() {
        vec![(0, input.len())]
    } else {
        get_lang_intervals(input, lang_scopes, join_lang)
    };

    let mut detailed_matches: Vec<(usize, usize, HashMap<String,String>)> = Vec::new();
    for (ls, le) in &lang_intervals {
        let slice = &input[*ls..*le];
        for caps in scope_regex.captures_iter(slice) {
            if let Some(m) = caps.get(0) {
                let s = ls + m.start();
                let e = ls + m.end();
                let mut map = HashMap::new();
                for i in 0..caps.len() {
                    if let Some(c) = caps.get(i) {
                        map.insert(i.to_string(), c.as_str().to_string());
                    }
                }
                for name in scope_regex.capture_names().flatten() {
                    if let Some(c) = caps.name(name) {
                        map.insert(name.to_string(), c.as_str().to_string());
                    }
                }
                detailed_matches.push((s,e,map));
            }
        }
    }

    let in_scope = !detailed_matches.is_empty();

    if !has_actions {
        if !search_mode {
            return (input.to_string(), false);
        }
        let mut output = String::new();
        let lines: Vec<&str> = input.lines().collect();
        let mut line_offsets = Vec::new();
        let mut off = 0;
        for line in &lines {
            line_offsets.push(off);
            off += line.len()+1;
        }
        let mut by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
        for (s,e,_) in &detailed_matches {
            for (li, &lo) in line_offsets.iter().enumerate() {
                let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                if *s >= lo && *s < next {
                    let cs = s - lo;
                    let ce = e - lo;
                    let line_len = lines[li].len();
                    by_line.entry(li).or_default().push((std::cmp::min(cs,line_len), std::cmp::min(ce,line_len)));
                    break;
                }
            }
        }
        let show_line = line_numbers || !lang_scopes.is_empty();
        if show_line {
            if only_matching {
                for (li, cols) in &by_line {
                    let range_str = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                    output.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, range_str, lines[*li]));
                }
            } else {
                for (li, line) in lines.iter().enumerate() {
                    if let Some(cols) = by_line.get(&li) {
                        let range_str = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        output.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, range_str, line));
                    } else {
                        output.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                    }
                }
            }
        } else {
            if only_matching {
                for (li, cols) in &by_line {
                    let range_str = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                    output.push_str(&format!("{}:{}:{}\n", filename, range_str, lines[*li]));
                }
            } else {
                for line in &lines {
                    output.push_str(&format!("{}\n", line));
                }
            }
        }
        return (output, in_scope);
    } else {
        if delete {
            let mut result = String::new();
            let mut last = 0;
            let mut sorted = detailed_matches.clone();
            sorted.sort_by_key(|(s,_,_)| *s);
            for (s,e,_) in sorted {
                result.push_str(&input[last..s]);
                last = e;
            }
            result.push_str(&input[last..]);
            if line_numbers || only_matching {
                let mut out = String::new();
                let orig_lines: Vec<&str> = input.lines().collect();
                let mod_lines: Vec<&str> = result.lines().collect();
                let mut line_offsets = Vec::new();
                let mut off=0;
                for line in &orig_lines { line_offsets.push(off); off+=line.len()+1; }
                let mut by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
                for (s,e,_) in &detailed_matches {
                    for (li, &lo) in line_offsets.iter().enumerate() {
                        let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                        if *s >= lo && *s < next {
                            by_line.entry(li).or_default().push((s-lo, e-lo));
                            break;
                        }
                    }
                }
                if only_matching {
                    if line_numbers {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, mod_c));
                        }
                    } else {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}\n", filename, rs, mod_c));
                        }
                    }
                } else {
                    for (li, line) in mod_lines.iter().enumerate() {
                        if let Some(cols) = by_line.get(&li) {
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, line));
                        } else {
                            out.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                        }
                    }
                }
                return (out, in_scope);
            }
            return (result, in_scope);
        }
        if squeeze {
            let mut result = String::new();
            let mut last_end = 0;
            let mut sorted = detailed_matches.clone();
            sorted.sort_by_key(|(s,_,_)| *s);
            let mut prev_end = None;
            for (s,e,_) in sorted {
                result.push_str(&input[last_end..s]);
                if let Some(pe) = prev_end {
                    if s == pe {
                        // skip
                    } else {
                        result.push_str(&input[s..e]);
                        prev_end = Some(e);
                    }
                } else {
                    result.push_str(&input[s..e]);
                    prev_end = Some(e);
                }
                last_end = e;
            }
            result.push_str(&input[last_end..]);
            if line_numbers || only_matching {
                let mut out = String::new();
                let orig_lines: Vec<&str> = input.lines().collect();
                let mod_lines: Vec<&str> = result.lines().collect();
                let mut line_offsets = Vec::new();
                let mut off=0;
                for line in &orig_lines { line_offsets.push(off); off+=line.len()+1; }
                let mut by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
                for (s,e,_) in &detailed_matches {
                    for (li, &lo) in line_offsets.iter().enumerate() {
                        let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                        if *s >= lo && *s < next {
                            by_line.entry(li).or_default().push((s-lo, e-lo));
                            break;
                        }
                    }
                }
                if only_matching {
                    if line_numbers {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, mod_c));
                        }
                    } else {
                        for (li, cols) in &by_line {
                            let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}\n", filename, rs, mod_c));
                        }
                    }
                } else {
                    for (li, line) in mod_lines.iter().enumerate() {
                        if let Some(cols) = by_line.get(&li) {
                            let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                            out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, line));
                        } else {
                            out.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                        }
                    }
                }
                return (out, in_scope);
            }
            return (result, in_scope);
        }

        let mut sorted = detailed_matches.clone();
        sorted.sort_by_key(|(s,_,_)| *s);
        let mut result = String::new();
        let mut last_end = 0;
        let mut adjusted_by_line: HashMap<usize, Vec<(usize,usize)>> = HashMap::new();
        let mut line_offsets = Vec::new();
        {
            let lines: Vec<&str> = input.lines().collect();
            let mut off=0;
            for line in &lines { line_offsets.push(off); off+=line.len()+1; }
        }
        let mut delta: isize = 0;
        for (s,e,caps) in &sorted {
            result.push_str(&input[last_end..*s]);
            let mut seg = input[*s..*e].to_string();
            if let Some(rep) = &replacement {
                seg = expand_replacement(rep, caps.clone());
            }
            if upper { seg = seg.to_uppercase(); }
            if lower { seg = seg.to_lowercase(); }
            if titlecase { seg = titlecase_transform(&seg); }
            if normalize { seg = normalize_transform(&seg); }
            if symbols {
                if invert { seg = symbols_invert(&seg); } else { seg = symbols_transform(&seg); }
            }
            if german {
                seg = german_transform(&seg, german_naive, german_prefer_original, invert && !symbols);
            }
            let new_len = seg.len() as isize;
            let orig_len = (*e as isize - *s as isize);
            // compute line for adjusted
            for (li, &lo) in line_offsets.iter().enumerate() {
                let next = if li+1 < line_offsets.len() { line_offsets[li+1] } else { input.len()+1 };
                if *s >= lo && *s < next {
                    let cs = (*s - lo) as isize + delta;
                    let ce = cs + new_len;
                    adjusted_by_line.entry(li).or_default().push((cs as usize, ce as usize));
                    break;
                }
            }
            delta += new_len - orig_len;
            result.push_str(&seg);
            last_end = *e;
        }
        result.push_str(&input[last_end..]);

        if line_numbers || only_matching {
            let mut out = String::new();
            let mod_lines: Vec<&str> = result.lines().collect();
            if only_matching {
                if line_numbers {
                    for (li, cols) in &adjusted_by_line {
                        let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                        let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, mod_c));
                    }
                } else {
                    for (li, cols) in &adjusted_by_line {
                        let mod_c = if *li < mod_lines.len() { mod_lines[*li] } else { "" };
                        let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        out.push_str(&format!("{}:{}:{}\n", filename, rs, mod_c));
                    }
                }
            } else {
                for (li, line) in mod_lines.iter().enumerate() {
                    if let Some(cols) = adjusted_by_line.get(&li) {
                        let rs = cols.iter().map(|(a,b)| format!("{}-{}", a,b)).collect::<Vec<_>>().join(";");
                        out.push_str(&format!("{}:{}:{}:{}\n", filename, li+1, rs, line));
                    } else {
                        out.push_str(&format!("{}:{}::{}\n", filename, li+1, line));
                    }
                }
            }
            return (out, in_scope);
        }

        return (result, in_scope);
    }
}

fn expand_replacement(rep: &str, caps: HashMap<String,String>) -> String {
    let mut result = String::new();
    let mut chars = rep.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '$' {
            if let Some(&next) = chars.peek() {
                if next == '$' {
                    result.push('$'); chars.next();
                } else if next.is_ascii_digit() {
                    let mut num = String::new();
                    while let Some(&d) = chars.peek() {
                        if d.is_ascii_digit() { num.push(d); chars.next(); } else { break; }
                    }
                    if let Some(v) = caps.get(&num) { result.push_str(v); }
                } else if next == '{' {
                    chars.next();
                    let mut name = String::new();
                    while let Some(ch) = chars.next() {
                        if ch == '}' { break; } else { name.push(ch); }
                    }
                    if let Some(v) = caps.get(&name) { result.push_str(v); }
                } else if next.is_alphabetic() || next == '_' {
                    let mut name = String::new();
                    while let Some(&ch) = chars.peek() {
                        if ch.is_alphanumeric() || ch == '_' { name.push(ch); chars.next(); } else { break; }
                    }
                    if let Some(v) = caps.get(&name) { result.push_str(v); }
                } else {
                    result.push('$');
                }
            } else {
                result.push('$');
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn titlecase_transform(s: &str) -> String {
    // Simplified titlecase that matches earlier approximation
    // We'll reuse logic from earlier that passed most tests
    let delims: Vec<char> = vec![',','/','-',';','!','?','{','}','"','#','$','%','^','*','+','=','<','>','|','\\','`','~'];
    let delims_set: std::collections::HashSet<char> = delims.into_iter().collect();

    // Split by whitespace preserving
    let re_ws = Regex::new(r"(\s+)").unwrap();
    let ws_parts: Vec<&str> = re_ws.split(s).collect();
    let ws_seps: Vec<&str> = re_ws.find_iter(s).map(|m| m.as_str()).collect();

    // Collect all subwords for case analysis
    let mut all_words: Vec<String> = Vec::new();
    for part in re_ws.split(s) {
        if part.trim().is_empty() { continue; }
        // split by delims
        let mut current = String::new();
        for ch in part.chars() {
            if delims_set.contains(&ch) {
                if !current.is_empty() { all_words.push(current.clone()); current.clear(); }
            } else {
                current.push(ch);
            }
        }
        if !current.is_empty() { all_words.push(current); }
    }

    let mut has_lower = false;
    let mut has_upper = false;
    let mut has_mixed = false;
    for w in &all_words {
        if w.chars().all(|c| !c.is_alphabetic()) { continue; }
        let is_lower = w.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_lowercase());
        let is_upper = w.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_uppercase());
        if is_lower { has_lower = true; }
        else if is_upper { has_upper = true; }
        else {
            // Check if title
            let mut chars = w.chars().filter(|c| c.is_alphabetic());
            if let Some(first) = chars.next() {
                if first.is_uppercase() && chars.clone().all(|c| c.is_lowercase()) {
                    // title
                } else {
                    has_mixed = true;
                }
            } else {
                has_mixed = true;
            }
        }
    }

    let convert_lower = if has_lower { true } else { false };
    let convert_upper = if !has_lower && !has_mixed && has_upper { true } else { false };

    // Now transform
    let mut result = String::new();
    let mut parts_iter = re_ws.split(s);
    let mut sep_iter = re_ws.find_iter(s).map(|m| m.as_str());
    // We need to interleave
    // re.split gives parts including empty? Let's use manual
    let mut last_end = 0;
    let ws_re = Regex::new(r"\s+").unwrap();
    let mut result2 = String::new();
    let mut last = 0;
    for m in ws_re.find_iter(s) {
        let start = m.start();
        let end = m.end();
        let token = &s[last..start];
        if !token.is_empty() {
            result2.push_str(&transform_token(token, &delims_set, convert_lower, convert_upper));
        }
        result2.push_str(m.as_str());
        last = end;
    }
    let token = &s[last..];
    if !token.is_empty() {
        result2.push_str(&transform_token(token, &delims_set, convert_lower, convert_upper));
    }
    result2
}

fn transform_token(token: &str, delims_set: &std::collections::HashSet<char>, convert_lower: bool, convert_upper: bool) -> String {
    let mut out = String::new();
    let mut current = String::new();
    for ch in token.chars() {
        if delims_set.contains(&ch) {
            if !current.is_empty() {
                out.push_str(&transform_word(&current, convert_lower, convert_upper));
                current.clear();
            }
            out.push(ch);
        } else {
            current.push(ch);
        }
    }
    if !current.is_empty() {
        out.push_str(&transform_word(&current, convert_lower, convert_upper));
    }
    out
}

fn transform_word(word: &str, convert_lower: bool, convert_upper: bool) -> String {
    // Classify word
    let cased: Vec<char> = word.chars().filter(|c| c.is_alphabetic()).collect();
    if cased.is_empty() { return word.to_string(); }
    let is_lower = cased.iter().all(|c| c.is_lowercase());
    let is_upper = cased.iter().all(|c| c.is_uppercase());
    let is_title = {
        if let Some(first) = cased.first() {
            first.is_uppercase() && cased.iter().skip(1).all(|c| c.is_lowercase())
        } else { false }
    };
    if is_lower && convert_lower {
        // Titlecase: first alpha upper, rest lower
        let mut chars: Vec<char> = word.chars().collect();
        let mut first_found = false;
        for i in 0..chars.len() {
            if chars[i].is_alphabetic() {
                if !first_found {
                    chars[i] = chars[i].to_uppercase().next().unwrap_or(chars[i]);
                    first_found = true;
                } else {
                    chars[i] = chars[i].to_lowercase().next().unwrap_or(chars[i]);
                }
            }
        }
        chars.into_iter().collect()
    } else if is_upper && convert_upper {
        let mut chars: Vec<char> = word.chars().collect();
        let mut first_found = false;
        for i in 0..chars.len() {
            if chars[i].is_alphabetic() {
                if !first_found {
                    chars[i] = chars[i].to_uppercase().next().unwrap_or(chars[i]);
                    first_found = true;
                } else {
                    chars[i] = chars[i].to_lowercase().next().unwrap_or(chars[i]);
                }
            }
        }
        chars.into_iter().collect()
    } else {
        word.to_string()
    }
}

fn normalize_transform(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        let mapped = match c {
            'À'|'Á'|'Â'|'Ã'|'Ä'|'Å' => 'A',
            'à'|'á'|'â'|'ã'|'ä'|'å' => 'a',
            'Ç' => 'C', 'ç' => 'c',
            'È'|'É'|'Ê'|'Ë' => 'E',
            'è'|'é'|'ê'|'ë' => 'e',
            'Ì'|'Í'|'Î'|'Ï' => 'I',
            'ì'|'í'|'î'|'ï' => 'i',
            'Ñ' => 'N', 'ñ' => 'n',
            'Ò'|'Ó'|'Ô'|'Õ'|'Ö' => 'O',
            'ò'|'ó'|'ô'|'õ'|'ö' => 'o',
            'Ù'|'Ú'|'Û'|'Ü' => 'U',
            'ù'|'ú'|'û'|'ü' => 'u',
            'Ý' => 'Y', 'ý'|'ÿ' => 'y',
            'ß' => 's', 'ẞ' => 'S',
            _ => c,
        };
        result.push(mapped);
    }
    result
}

fn symbols_transform(s: &str) -> String {
    let mappings = vec![
        ("-->", "⟶"),
        ("<--", "⟵"),
        ("<->", "↔"),
        ("---", "—"),
        ("--", "–"),
        ("->", "→"),
        ("<-", "←"),
        ("=>", "⇒"),
        ("<=", "≤"),
        (">=", "≥"),
        ("!=", "≠"),
    ];
    let mut out = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let mut matched = false;
        for (a,u) in &mappings {
            let ac: Vec<char> = a.chars().collect();
            if i+ac.len() <= chars.len() {
                let slice: String = chars[i..i+ac.len()].iter().collect();
                if slice == *a {
                    out.push_str(u);
                    i+=ac.len();
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            out.push(chars[i]);
            i+=1;
        }
    }
    out
}

