fn get_ranges_for_line(line: &str, scope_pattern: &str, literal: bool) -> Vec<(usize,usize)> {
    let re = if literal {
        Regex::new(&regex::escape(scope_pattern)).unwrap_or_else(|_| Regex::new(".*").unwrap())
    } else {
        Regex::new(scope_pattern).unwrap_or_else(|_| Regex::new(".*").unwrap())
    };
    re.find_iter(line).map(|m| (m.start(), m.end())).collect()
}

fn build_cli() -> Command {
    Command::new("srgn")
        .version("0.14.1")
        .about("A grep-like tool which understands source code syntax and allows for manipulation in addition to search")
        .arg(Arg::new("SCOPE").help("Scope to apply to, as a regular expression pattern.\n\nIf string literal mode is requested, will be interpreted as a literal string.\n\nActions will apply their transformations within this scope only.\n\nThe default is the global scope, matching the entire input. Where that default is meaningless or dangerous (e.g., deletion), this argument is required.\n\n[default: .*]").default_value(".*"))
        .arg(Arg::new("REPLACEMENT").help("Replace anything in scope with this value.\n\nVariables are supported: if a regex pattern was used for scoping and captured content in named or numbered capture groups, access these in the replacement value using `$1` etc. for numbered, `$NAME` etc. for named capture groups.\n\nThis action is specially treated as a positional argument for ergonomics and compatibility with `tr`.\n\nIf given, will run before any other action.\n\n[env: REPLACE=]").value_name("REPLACEMENT").last(true).env("REPLACE"))
        .arg(Arg::new("completions").long("completions").value_name("SHELL").help("Print shell completions for the given shell.\n\n[possible values: bash, elvish, fish, powershell, zsh]").value_parser(["bash","elvish","fish","powershell","zsh"]))
        .arg(Arg::new("upper").short('u').long("upper").help("Uppercase anything in scope.\n\n[env: UPPER=]").action(ArgAction::SetTrue).env("UPPER").value_parser(value_parser!(bool)))
        .arg(Arg::new("lower").short('l').long("lower").help("Lowercase anything in scope.\n\n[env: LOWER=]").action(ArgAction::SetTrue).env("LOWER").value_parser(value_parser!(bool)))
        .arg(Arg::new("titlecase").short('t').long("titlecase").help("Titlecase anything in scope.\n\n[env: TITLECASE=]").action(ArgAction::SetTrue).env("TITLECASE").value_parser(value_parser!(bool)))
        .arg(Arg::new("normalize").short('n').long("normalize").help("Normalize (Normalization Form D) anything in scope, and throw away marks.\n\n[env: NORMALIZE=]").action(ArgAction::SetTrue).env("NORMALIZE").value_parser(value_parser!(bool)))
        .arg(Arg::new("german").short('g').long("german").help("Perform substitutions on German words, such as 'Abenteuergruesse' to 'Abenteuergrüße', for anything in scope.\n\nASCII spellings for Umlauts (ae, oe, ue) and Eszett (ss) are replaced by their respective native Unicode (ä, ö, ü, ß).\n\nArbitrary compound words are supported.\n\nWords legally containing alternative spellings are not modified.\n\nWords require correct spelling to be detected.").action(ArgAction::SetTrue).env("GERMAN").value_parser(value_parser!(bool)))
        .arg(Arg::new("symbols").short('S').long("symbols").help("Perform substitutions on symbols, such as '!=' to '≠', '->' to '→', on anything in scope.\n\nHelps translate 'ASCII art' into native Unicode representations.").action(ArgAction::SetTrue))
        .arg(Arg::new("delete").short('d').long("delete").help("Delete anything in scope.\n\nCannot be used with any other action: there is no point in deleting and performing any other processing. Sibling actions would either receive empty input or have their work wiped.").action(ArgAction::SetTrue))
        .arg(Arg::new("squeeze").short('s').long("squeeze").aliases(["squeeze-repeats"]).help("Squeeze consecutive occurrences of scope into one.\n\n[env: SQUEEZE=]\n[aliases: squeeze-repeats]").action(ArgAction::SetTrue).env("SQUEEZE").value_parser(value_parser!(bool)))
        .arg(Arg::new("glob").short('G').long("glob").value_name("GLOB").help("Glob of files to work on (instead of reading stdin).\n\nIf actions are applied, they overwrite files in-place.\n\nFor supported glob syntax, see:\n<https://docs.rs/glob/0.3.1/glob/struct.Pattern.html>\n\nNames of processed files are written to stdout.").action(ArgAction::Append))
        .arg(Arg::new("fail-no-files").long("fail-no-files").help("Fail if working on files (e.g. globbing is requested) but none are found.\n\nProcessing no files is not an error condition in itself, but might be an unexpected outcome in some contexts. This flag makes the condition explicit.").action(ArgAction::SetTrue))
