        .arg(Arg::new("invert").short('i').long("invert").help("Undo the effects of passed actions, where applicable.\n\nRequires a 1:1 mapping between replacements and original, which is currently available only for:\n\n- symbols: '≠' <-> '!=' etc.\n\nOther actions:\n\n- german: inverting e.g. 'Ä' is ambiguous (can be 'Ae' or 'AE')\n\n- upper, lower, deletion, squeeze: inversion is impossible as information is lost\n\nThese may still be passed, but will be ignored for inversion and applied normally.\n\n[env: INVERT=]").action(ArgAction::SetTrue).env("INVERT").value_parser(value_parser!(bool)))
