    let stdin_readable_auto = {
        if io::stdin().is_terminal() {
            false
        } else {
            // Try to read stdin to see if it has data
            let mut buf = String::new();
            // We need to read without blocking too long; read_to_string will return empty if EOF
            let mut stdin = io::stdin();
            // Use read_to_string, but if no data, it returns empty immediately in this env
            let read_result = stdin.read_to_string(&mut buf);
            match read_result {
                Ok(_) => {
                    if buf.is_empty() {
                        // Empty stdin: if we have file mode requested (glob or lang), treat as not readable
                        if !glob_patterns.is_empty() || !lang_scopes.is_empty() {
                            false
                        } else {
                            // No file mode, treat as readable (empty input)
                            stdin_buffer = Some(buf);
                            true
                        }
                    } else {
                        stdin_buffer = Some(buf);
                        true
                    }
                }
                Err(_) => false,
            }
        }
    };

    let stdin_readable = match stdin_detection.as_str() {
        "force-readable" => true,
        "force-unreadable" => false,
        "auto" => stdin_readable_auto,
        _ => stdin_readable_auto,
    };

    let _stdout_is_tty = match stdout_detection.as_str() {
        "force-tty" => true,
        "force-pipe" => false,
        "auto" => io::stdout().is_terminal(),
        _ => io::stdout().is_terminal(),
    };

    if stdin_readable {
        if !glob_patterns.is_empty() {
            log::error!("Detected stdin, and request for files: will use stdin and ignore files.");
        }
        let input = if let Some(buf) = stdin_buffer {
            buf
        } else {
            // If forced readable and we haven't read yet, read now
            let mut input = String::new();
            io::stdin().read_to_string(&mut input).unwrap();
            input
        };"""

text = text.replace(old, new)
p.write_text(text)
print("patched stdin")
