use clap::{Command, Arg, ArgAction, value_parser};
use clap_complete::{generate, Shell};
use std::collections::{HashMap, HashSet};
use std::io::{self, Read, IsTerminal};
use std::fs;
use std::path::PathBuf;
use regex::Regex;
use glob::glob;

const SHORT_HELP: &str = include_str!("../completions/short_help.txt");
const LONG_HELP: &str = include_str!("../completions/long_help.txt");
const BASH_COMPLETION: &str = include_str!("../completions/bash.txt");
const ZSH_COMPLETION: &str = include_str!("../completions/zsh.txt");
const FISH_COMPLETION: &str = include_str!("../completions/fish.txt");
const ELVISH_COMPLETION: &str = include_str!("../completions/elvish.txt");
const POWERSHELL_COMPLETION: &str = include_str!("../completions/powershell.txt");

fn main() {
    let _ = env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("error")).try_init();
    let args: Vec<String> = std::env::args().collect();

    // Handle --completions, -h, --help, -V, --version manually to match original exactly
    for (i, a) in args.iter().enumerate() {
        if a == "--completions" {
            if i+1 < args.len() {
                let shell_str = &args[i+1];
                match shell_str.as_str() {
                    "bash" => { print!("{}", BASH_COMPLETION); return; },
                    "zsh" => { print!("{}", ZSH_COMPLETION); return; },
                    "fish" => { print!("{}", FISH_COMPLETION); return; },
                    "elvish" => { print!("{}", ELVISH_COMPLETION); return; },
                    "powershell" => { print!("{}", POWERSHELL_COMPLETION); return; },
                    _ => {
                        eprintln!("error: invalid value '{}' for '--completions <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", shell_str);
                        std::process::exit(2);
                    }
                }
            } else {
                eprintln!("error: a value is required for '--completions <SHELL>' but none was supplied\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
        if a == "-h" || a == "--help" {
            if a == "-h" {
                print!("{}", SHORT_HELP);
            } else {
                print!("{}", LONG_HELP);
            }
            return;
        }
        if a == "-V" || a == "--version" {
            println!("srgn 0.14.1");
            return;
        }
    }

    let cmd = build_cli();
    let matches = match cmd.try_get_matches_from(std::env::args()) {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };

    let scope_pattern = matches.get_one::<String>("SCOPE").cloned().unwrap_or_else(|| ".*".to_string());
    let replacement = matches.get_one::<String>("REPLACEMENT").cloned();

    let upper = matches.get_flag("upper");
    let lower = matches.get_flag("lower");
    let titlecase = matches.get_flag("titlecase");
    let normalize = matches.get_flag("normalize");
    let german = matches.get_flag("german");
    let symbols = matches.get_flag("symbols");
    let delete = matches.get_flag("delete");
    let squeeze = matches.get_flag("squeeze");

    let glob_patterns: Vec<String> = matches.get_many::<String>("glob").map(|v| v.cloned().collect()).unwrap_or_default();

    let fail_no_files = matches.get_flag("fail-no-files");
    let dry_run = matches.get_flag("dry-run");
    let invert = matches.get_flag("invert");
    let literal_string = matches.get_flag("literal-string");
    let fail_any = matches.get_flag("fail-any");
    let fail_none = matches.get_flag("fail-none");
    let join_lang = matches.get_flag("join-language-scopes");
    let hidden = matches.get_flag("hidden");
    let gitignored = matches.get_flag("gitignored");
    let sorted = matches.get_flag("sorted");
    let stdin_detection = matches.get_one::<String>("stdin-detection").cloned().unwrap_or_else(|| "auto".to_string());
    let stdout_detection = matches.get_one::<String>("stdout-detection").cloned().unwrap_or_else(|| "auto".to_string());
    let line_numbers = matches.get_flag("line-numbers");
    let only_matching = matches.get_flag("only-matching");

    let german_prefer_original = matches.get_flag("german-prefer-original");
    let german_naive = matches.get_flag("german-naive");

