    macro_rules! collect_lang {
        ($arg_name:expr, $lang:expr) => {
            if let Some(vals) = matches.get_many::<String>($arg_name) {
                for v in vals {
                    lang_scopes.push(($lang.to_string(), v.clone()));
                }
            }
        };
    }
